_A7 = [("Anchor", "Ang sunud-sunod na pagsusulpot at paggamit ng makabagong teknolohiya at kagamitan ay posibleng makaapekto sa ugali ng isang tao.", "The successive emergence and use of modern technology and equipment can possibly affect a person’s behavior."), ("Anchor", "Ayon kay Doktora Bernadette Arsenas, spokesperson ng Philippine Psychiatric Society ang utak ng tao ay parang ispongha na kung anu-anong nakikita at nararanasan ay tumatatak sa isip.", "According to Doctor Bernadette Arsenas, spokesperson of the Philippine Psychiatric Society, the human brain is like a sponge, and whatever is seen and experienced is imprinted in the mind."), ("Anchor", "Sinabi ni Arsenas na totoo ito lalo na sa mga bata na sa pagtungtong ng high school ay nahubog na ang pag-uugali.", "Arsenas said this is especially true for children, whose character is already formed by the time they reach high school."), ("Anchor", "Kung minsan ang karahasan sa mga computer games o paglabas sa TV ay tumatatak din sa kaisipan at pananaw ng sinuman.", "Sometimes, violence in computer games or on TV also imprints on anyone’s mind and outlook."), ("Anchor", "Kaugnay nito, sinabi ni Arsenas na mahalaga ang gabay at payo ng mga magulang o nakakatanda upang makontrol ang panonood ng TV o paglalaro ng computer.", "In this connection, Arsenas said that the guidance and advice of parents or elders are important in controlling TV watching or computer playing."), ("Anchor", "Alam mo ’yung pag-lock nga ng mga tinatawag natin na mga sites na hindi katangi-tangi sa mata ng isang bata ay kailangan talaga mabigyang-pansin ’yun.", "You know, the locking of what we call sites that are inappropriate in a child’s eyes really needs attention."), ("Anchor", "Kasi alam mo kung kahit saan ka pupunta, ’di ba? Madaming mga nakikita ka na mga internet cafe at ito ay isang factor kung bakit kahit wala sa TV ay nandun pa rin ’yung inpluwensiya ng teknolohiya.", "Because you know, wherever you go, right? You see many internet cafés, and this is a factor why even without TV the influence of technology is still there.")]
_A8 = [("Lumalakas ang sigaw na ipagbawal na ang video games sa kabataan at parusahan ang mga operators na lalabag dito.", "The cry to ban video games for the youth and to punish the operators who violate this is growing stronger."), ("Ang video games ang bagong kinalolokohan ng mga kabataan ngayon lalo na ng mga elementary at high school students.", "Video games are the new craze of the youth today, especially elementary and high school students."), ("Maraming estudyanteng lalaki ang addict na rito.", "Many male students are addicted to it."), ("Pagkagaling sa school ay video games na ang kanilang inaatupag na kadalasang nasa malapit sa mga eskuwelahan.", "After school they take care of video games, which are often near the schools."), ("Mayroon din nito sa mga mall na dinadayo rin ng mga estudyante.", "There are also some in the malls, which students also flock to."), ("Dahil sa pagkalulong sa video games ay maraming estudyante ang napapabayaan ang kanilang pag-aaral.", "Because of addiction to video games, many students neglect their studies."), ("Isa sa kinalolokohang games ay ang counter strike.", "One of the craze games is Counter-Strike."), ("Ang murang isipan ng bata ay namumulat sa karahasan kung kaya madalas na mapasubo sa away at nagiging violent.", "The young mind of the child becomes aware of violence, which is why they often get into fights and become violent."), ("Dahil din sa pagka-addict sa video games kaya marami ang umaabsent at naglalakwatsa para lang maglaro.", "Also because of video game addiction, many are absent and go roaming just to play."), ("Ang kanilang allowance ang ginagastos.", "Their allowance is what is spent."), ("May mga natuto na ring mang-umit sa mga magulang.", "Some have even learned to steal from their parents."), ("Ang pagsisinungaling at pandaraya ay maagang natututuhan ng mga batang lulong na sa video games.", "Lying and cheating are learned early by children already hooked on video games."), ("Tularan nga sana ang Makati City ng iba pang lugar sa bansa para ipatupad ang pagbabawal sa mga estudyante na maglaro ng video games para hindi maapektuhan ang kanilang pag-aaral.", "May other places in the country follow Makati City in implementing the ban on students playing video games so their studies are not affected.")]
_K8 = [("1", "Ban video games for the youth and punish the operators who will violate the law."), ("2", "Because of addiction to video games, so many students neglect their studies."), ("3", "The innocent minds of the children become aware of violence, which is why they are often engaged in fights and become violent themselves."), ("4", "Children addicted to video games learn lying and cheating early on."), ("5", "Implement the ban against students playing video games so they will not neglect their studies.")]
_A9 = [("Kasabay ng pag-unlad ng teknolohiya, hindi nakakapagtaka na talamak ang nagsusulputang mga kawatan, manggagantso at mapanlinlang.", "Along with the advance of technology, it is no wonder that thieves, swindlers and deceivers keep sprouting up."), ("Ang kanilang estilo sa panggagantso, high-tech na rin.", "Their style of swindling is high-tech too."), ("Ang kakapal ng mukha na magnakaw ng identidad at pagkakakilanlan ng isang indibidwal.", "How thick-faced they are to steal the identity of an individual."), ("Napakadali na lang magnakaw ng identidad sa panahon ngayon.", "It is very easy to steal an identity nowadays."), ("Kahit sino, pwedeng maging sino sa pamamagitan lamang ng pagkukubli sa mga pekeng account sa internet.", "Anyone can become anybody just by hiding behind fake accounts on the internet."), ("Ang masaklap, magamit ang pangalan mo sa mga kalokohan at ilegal na aktibidades.", "The sad part is your name being used for foolishness and illegal activities."), ("Kaya sa mga techi, na pribadong indibidwal, mahalagang pag-aralan at pag-isipan munang mabuti ang lahat ng mga ipo-post at ilalabas sa mga social networking site.", "So for the techies, who are private individuals, it is important to study and think carefully first about everything they will post and release on social networking sites."), ("Mas mabuti pa ring maging pribado nang hindi kayo malagay sa alanganin.", "It is still better to be private so you will not be put in danger.")]
