        card("Activity 11: the book’s chart", "", tables=[table(["Affected area", "Ill effects or signs", "Other information"], _C11, say=[])]),
        card("Activity 12: how social networking sites can negatively affect one’s life (the book’s scripts)", "Listen to the segments and answer the questions. The audio is left out. Source: YouTube. The book’s script of questions 3 and 4 is joined to the last passage here.", examples=passage(_A12)),
        card("Activity 12: the book’s answers", "", tables=[table(["Question", "Answer"], _K12, say=[])]),
