_B = [("Kapag kumakanta sa harap ng stove ang isang dalaga ay makakapangasawa siya ng biyudo.", "When a young woman sings in front of the stove, she will marry a widower.", "superstition"), ("Magiging maunlad ang pagsasama kapag ikinasal kung kabilugan ng buwan.", "The married life will be prosperous if one marries on a full moon.", "superstition"), ("Iwasan ang tumingin ng direkta sa araw, dahil baka ikaw ay maparusahan.", "Avoid looking directly at the sun, because you might be punished.", "scientific basis (it can damage the eyes), though the reason given, punishment, is superstition"), ("Ang pagkabungi sa panaginip ay tanda ng pagkawala ng isang malapit na kaanak.", "Losing a tooth in a dream is a sign of losing a close relative.", "superstition"), ("Kapag nagkakagulo ang mga hayop, may nalalapit na panganib.", "When the animals are in an uproar, danger is near.", "some scientific basis (animals can sense earthquakes or storms)"), ("Kapag nilapastangan o inabuso ang kapaligiran ikaw ay mapaparusahan.", "If you disrespect or abuse the environment, you will be punished.", "scientific basis (environmental damage brings disasters), told as punishment"), ("Malas ang makasalubong ng itim na pusa sa daan.", "It is bad luck to meet a black cat on the road.", "superstition"), ("Kapag nakawala ng isang bagay, pumunta sa isang manghuhula. Malalaman niya kung nasaan ang nawawalang bagay.", "When you lose something, go to a fortune teller. He or she will know where the lost thing is.", "superstition"), ("Kapag nakahuli ng maliliit na isda, ibalik ito sa dagat para hindi maparusahan.", "When you catch small fish, return them to the sea so you will not be punished.", "scientific basis (conservation of the fish supply), told as punishment"), ("Kapag sinuway ang utos ng magulang ay dadanas ng hirap at gagapang na parang ahas.", "When a parent’s order is disobeyed, you will suffer hardship and crawl like a snake.", "superstition; a cultural lesson in obedience")]
_S14 = [("Maraming hindi kanais-nais ang dulot ng internet gaya ng karahasan, kalaswaan, at pagnanakaw ng pagkakakilanlan.", "The internet brings many undesirable things such as violence, obscenity and identity theft."), ("Ang mga pataba at pamatay-insekto ay nakakasira sa mga pananim, kapaligiran, at kalusugan ng tao.", "Fertilizers and insecticides damage crops, the environment and human health."), ("Ang modernong transportasyon ay nagdudulot ng panganib sa kapaligiran at kalusugan ng tao.", "Modern transportation brings danger to the environment and human health.")]
_G = [("amoy", "smell"), ("bagong sibol", "new breed"), ("hindi isinaalang-alang", "did not consider; did not take into consideration"), ("hindi katangi-tangi", "inappropriate"), ("imbensyon", "invention"), ("imbentor", "inventor"), ("inaangkin", "being claimed by others"), ("ispongha", "sponge"), ("kaagahan", "early (years)"), ("kamulatan", "awareness"), ("kapansin-pansin", "noticeable"), ("lumitaw", "emerged"), ("malala", "worse"), ("malalaswa", "obscene"), ("naimbento", "invented"), ("nakakabahala", "alarming"), ("nakasalalay", "contingent; dependent"), ("naniniwala", "believe"), ("napapansin", "notice"), ("napatunayan", "was proven"), ("napipilitang", "being forced"), ("ninanakaw", "being stolen"), ("padaliin", "speed up; accelerate; facilitate"), ("paghubog", "molding"), ("pagsulpot", "emergence"), ("pag-uugali", "attitude"), ("pahintayin", "to make someone wait"), ("paigtingin", "to intensify something"), ("paintindihin", "to make someone understand"), ("palawakin", "to widen something; to make something extensive"), ("palawigin", "to extend something; to make something extensive"), ("panganib", "danger"), ("paunlarin", "to make something better"), ("siyentipiko", "scientist"), ("tambutso", "muffler; exhaust"), ("tumatatak", "is imprinted")]
_SS = [("Ang teknolohiya ay maaaring mabuti o masama, depende sa paggamit.", "Technology can be good or bad, depending on its use. (my sentence)"), ("Pinahintay ng guro ang mga estudyante sa labas.", "The teacher had the students wait outside. (my sentence)"), ("Dapat paunlarin ng pamahalaan ang agham at teknolohiya.", "The government should develop science and technology. (my sentence)")]
